(()=>{
const root=document.getElementById('prime-square-campaigns'),screen=root.querySelector('#ps-screen');

let loaded=false,loadError=false,revealBusy=false,deleteBusy=false;
function readLocal(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}
function writeLocal(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}
async function server(path,body){const bridge=window.webkit?.messageHandlers?.primeAPI;if(!bridge)throw Error('Mobil bağlantı başlatılamadı.');const r=await bridge.postMessage({path,body:body||null});if(r.status<200||r.status>=300)throw Error(r.data?.error||'İşlem tamamlanamadı.');return r.data;}
const expired=o=>Number(o?.expires)>0&&Number(o.expires)*1000<=Date.now();
function asset(value){const v=String(value||'');if(/^[\w.-]+\.(png|jpg|jpeg|webp|svg)$/.test(v))return 'assets/'+v;if(/^assets\/[\w.\/-]+$/.test(v))return v;try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
function website(value){try{const u=new URL(String(value||''));return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}}
function showError(message){const note=document.createElement('p');note.className='ps-copyerror';note.setAttribute('role','alert');note.textContent=message;(screen.querySelector('.ps-slidefooter')||screen).append(note);}
async function revealCode(){if(revealBusy||!current||expired(current))return;const campaign=current;revealBusy=true;try{const r=await server('reveal',{id:campaign.id});if(r.expired||expired(campaign))throw Error('Kampanya sona erdi.');if(!String(r.code||'').trim())throw Error('Kampanya kodu bulunamadı.');campaign.code=String(r.code);if(current===campaign&&view==='detail'){revealed=true;render();}}catch(e){showError(e.message);}finally{revealBusy=false;}}
function inferBenefits(c){if(Array.isArray(c.benefitCategories))return c.benefitCategories;const text=(c.offer+' '+c.description+' '+c.conditions).toLocaleLowerCase('tr');const rules=[['Sepette İndirim',/sepette.{0,30}indirim|sepet.{0,25}tl indirim/],['Ürün İndirimleri',/%\s*\d+.{0,15}indirim/],['İkinci Ürüne İndirim',/ikinci ürün|2\. ürün/],['Çoklu Alım ve Setler',/\bset|çoklu alım|\d+ alana/],['Hediyeli Alışveriş',/hediye/],['İlk Alışveriş',/ilk (alışveriş|sipariş)/],['Puan ve Para İadesi',/puan|para iadesi|cashback/],['Kargo Avantajı',/ücretsiz kargo|kargo bedava/],['Üyelere Özel',/üyelere özel|yeni üye/],['Ödeme Avantajları',/havale|taksit/]];return rules.filter(([,r])=>r.test(text)).map(([name])=>name);}
function hydrate(rows){offers=rows.filter(c=>!c.demo&&c.active!==0&&!expired(c)).map(c=>({id:String(c.id),brand:String(c.name||''),title:String(c.offer||''),sub:String(c.description||''),terms:[c.description,c.conditions].filter(Boolean).join('\n\n'),category:'',hasCode:!!Number(c.hasCode),code:'',mode:Number(c.hasCode)?'Kodlu':'Kodsuz',source:website(c.channel),expires:Number(c.expires)||0,expiry:Number(c.expires)>0?new Date(Number(c.expires)*1000).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul',dateStyle:'long',timeStyle:'short'}):'Bitiş tarihi belirtilmedi',benefitCategories:inferBenefits(c),raw:c}));brandNames=[...new Set(offers.map(o=>o.brand))];for(const o of offers){const c=o.raw;logos[o.brand]=asset(c.asset);campaignArt[o.id]={large:asset(c.verticalPhoto||c.photo),compact:asset(c.verticalPhoto||c.photo),square:asset(c.squarePhoto||c.photo),detail:asset(c.photo)};if(c.codeBannerPhoto)codeBannerArt[o.id]=asset(c.codeBannerPhoto);if(c.lastDayPhoto)lastDayArt[o.id]=asset(c.lastDayPhoto);const rate=c.discountPercent==null?String(c.offer||'').match(/%\s*(\d+(?:[.,]\d+)?)/)?.[1]:c.discountPercent;discountRates[o.id]=Number(String(rate??'').replace(',','.'))||0;}}
function offerTicket(o){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="400" viewBox="0 0 1200 400"><rect width="1200" height="400" rx="36" fill="#171719"/><text x="46" y="90" font-family="Arial" font-size="34" fill="#ff7276">KAMPANYA KODU</text><text x="46" y="166" font-family="Arial" font-size="40" fill="white">${esc(o.brand)}</text><text x="46" y="245" font-family="Arial" font-size="46" fill="white">${esc(o.title).slice(0,70)}</text><text x="46" y="340" font-family="Arial" font-size="28" fill="#ff7276">Kodu açmak için dokun</text></svg>`);}
async function start(){loaded=false;loadError=false;render();try{let me=await server('me');if(!me.authorized)await server('access',{});const r=await server('campaigns');hydrate(r.campaigns||[]);loaded=true;view='home';navigation.length=0;render();}catch(e){loadError=true;render();}}
async function deleteData(){if(deleteBusy)return;deleteBusy=true;try{await server('delete-account',{});favorites.clear();persistFavorites();settingsPhoto=null;writeLocal('lmprime-photo',null);navigation.length=0;await start();}catch(e){showError('Veriler silinemedi. Tekrar dene.');}finally{deleteBusy=false;}}
root.addEventListener('click',async e=>{const a=e.target.closest('a[href]');if(!a)return;e.preventDefault();const url=website(a.getAttribute('href'));if(!url){showError('Mağaza bağlantısı bulunmuyor.');return;}try{await server('open-external',{url});}catch(e){showError(e.message);}},true);
setInterval(()=>{if(!loaded||document.hidden)return;const active=offers.filter(o=>!expired(o));if(active.length===offers.length)return;offers=active;brandNames=[...new Set(offers.map(o=>o.brand))];if(view==='detail'&&expired(current)){copyNotice=false;revealed=false;view='home';}render();},1000);

let offers=[];
const campaignArt={};
let view='home',type='Tümü',usage='Tümü',brand='' ,query='',current=null,returnView='home',favorites=new Set(),revealed=false;
const storageKey='lmprime-favorites';
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(Array.isArray(saved))favorites=new Set(saved);}catch{}
function persistFavorites(){try{localStorage.setItem(storageKey,JSON.stringify([...favorites]));}catch{}}
const navigation=[];
function capturePage(){return {view,type,usage,brand,query,current,returnView,selectedCategory,discountThreshold,campaignBrand,campaignGroup,campaignOrigin,y:screen.scrollTop,rails:[...screen.querySelectorAll('.ps-carousel,.ps-coderail,.ps-lastdayrail,.ps-rounds,.ps-brandrounds,.ps-nativerail')].map(e=>e.scrollLeft)};}
function restorePage(p){({view,type,usage,brand,query,current,returnView,selectedCategory,discountThreshold,campaignBrand,campaignGroup,campaignOrigin}=p);render();screen.scrollTop=p.y;screen.querySelectorAll('.ps-carousel,.ps-coderail,.ps-lastdayrail,.ps-rounds,.ps-brandrounds,.ps-nativerail').forEach((e,i)=>e.scrollLeft=p.rails[i]||0);}
async function copyCurrentCode(){try{if(!current?.code||expired(current))throw Error('Kod kullanılamıyor.');await server('copy',{text:current.code});copyNotice=true;render();screen.querySelector('.ps-copyhandle')?.focus();}catch(e){showError('Kod panoya kopyalanamadı. Tekrar deneyebilirsin.');}}
const icon=n=>iconMarkup[n]||iconMarkup.tag||'';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const categoryAtlas='assets/support-7a77bc53df45be.webp';
const cats=[["Tümü","sparkles"],["Kampanya Kodu","ticket-percent"],["Son Gün","calendar-clock"],["Sepette İndirim","shopping-cart"],["Ürün İndirimleri","badge-percent"],["İkinci Ürüne İndirim","tags"],["Çoklu Alım ve Setler","shopping-basket"],["Hediyeli Alışveriş","gift"],["İlk Alışveriş","shopping-bag"],["Puan ve Para İadesi","coins"],["Kargo Avantajı","truck"],["Üyelere Özel","badge-check"],["Ödeme Avantajları","credit-card"]];
const categoryAtlasNames=["Kampanya Kodu","Sepette İndirim","Ürün İndirimleri","İkinci Ürüne İndirim","Çoklu Alım ve Setler","Hediyeli Alışveriş","İlk Alışveriş","Puan ve Para İadesi","Kargo Avantajı","Üyelere Özel","Ödeme Avantajları","Son Gün"];
function isLastDay(o,now=Date.now()){const end=Number(o.expires)*1000;return end>now&&end-now<86400000;}
function categoriesFor(o){const list=(o.benefitCategories||[]).filter(n=>n!=='Son Gün'&&n!=='Kampanya Kodu');if(o.hasCode)list.unshift('Kampanya Kodu');if(isLastDay(o))list.push('Son Gün');return [...new Set(list)];}
function header(){return `<header class="ps-header"><div class="ps-searchrow"><label class="ps-search">${icon('search')}<input id="ps-search" placeholder="Marka veya kampanya ara" aria-label="Marka veya kampanya ara" value="${esc(query)}"></label><button data-view="settings" class="ps-icon cursor-interaction" aria-label="Ayarları aç">${icon('settings-2')}</button></div></header>`}
function tag(o){const assigned=categoriesFor(o);const label=type!=='Tümü'&&assigned.includes(type)?type:assigned[0]||o.category;const glyph=cats.find(c=>c[0]===label)?.[1]||'tag';return `<div class="ps-tagrow"><span class="ps-tag">${icon(glyph)}${label}</span>${o.code&&label!=='Kampanya Kodu'?'<span class="ps-method">Kodlu</span>':''}</div>`}
function card(o){return poster(o,'feedcard')}
function matches(o){const method=o.mode||(o.id==='justin-club'?'Üyelik':'Kodsuz');return (type==='Tümü'||categoriesFor(o).includes(type))&&(usage==='Tümü'||usage===method)&&(o.brand+' '+o.title+' '+o.sub).toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr'))}
function feed(arr){return `<div class="ps-feed">${arr.filter(matches).map(card).join('')||'<div class="ps-empty">Bu kategoride kampanya yok.</div>'}</div>`}
function heading(title){return `<div class="ps-head"><h2>${title}</h2><button data-view="filter" class="ps-filter cursor-interaction">${icon('sliders-horizontal')}Filtrele</button></div>`}
function usageFilter(){return `<div class="ps-usage">${['Tümü','Kodlu','Kodsuz','Üyelik'].map(m=>`<button data-usage="${m}" class="cursor-interaction ${usage===m?'active':''}">${m}</button>`).join('')}</div>`}
function action(o){if(o.hasCode&&!revealed)return `<div class="ps-slide"><b>${icon('chevrons-right')}</b><label>Kodu görmek için sağa kaydır<input type="range" id="ps-reveal" min="0" max="100" value="0" aria-label="Kampanya kodunu açmak için sağa kaydır"></label></div><button class="ps-reveal cursor-interaction" data-reveal="1">Kodu göster</button>`;return `${o.code?`<div class="ps-code">${esc(o.code)}</div>`:''}<a class="ps-cta cursor-interaction" href="${esc(o.source)}" target="_blank" rel="noopener">${o.id==='justin-club'?'Club avantajlarına git':'Kampanyaya git'}</a>`}
let brandNames=[];
const palettes={"Celenes by Sweden":['#e9f0e7','#294c3d'],"Justin Beauty":['#f8e7ec','#663046'],"The Purest Solutions":['#e8edf6','#273b62'],"L'Occitane":['#fff2c9','#54431b'],"Caudalie":['#e7eee4','#345242'],"Flormar":['#fae3e7','#7d243a'],"Yves Rocher":['#edf0df','#45572c']};
const shortBrand=n=>n==='Celenes by Sweden'?'Celenes':n==='The Purest Solutions'?'The Purest':n;
const logos={};
function brandRounds(){return `<div class="ps-brandrounds" aria-label="Markalar">${brandNames.map(n=>`<button class="cursor-interaction" data-brand="${esc(n)}" aria-label="${esc(n)} kampanyalarını aç"><b><img src="${logos[n]}" alt="${esc(n)} logosu"></b><span class="ps-brandlabel">${esc(n)}</span></button>`).join('')}</div>`}
const imageCache={};
const digitalColors={"Celenes by Sweden":['#006d68','#004a49'],"Justin Beauty":['#a92a59','#602c53'],"The Purest Solutions":['#5c56ac','#323c70'],"L'Occitane":['#eabf39','#665020'],"Caudalie":['#476d44','#253e37'],"Flormar":['#f03758','#8e193e'],"Yves Rocher":['#5b791e','#253b26']};
const brandType={"Celenes by Sweden":"Trebuchet MS,Arial,sans-serif","Justin Beauty":"Georgia,Times New Roman,serif","The Purest Solutions":"Verdana,Arial,sans-serif","L'Occitane":"Palatino Linotype,Book Antiqua,serif","Caudalie":"Baskerville,Times New Roman,serif","Flormar":"Arial Narrow,Helvetica Neue,Arial,sans-serif","Yves Rocher":"Gill Sans,Trebuchet MS,sans-serif"};
const referencePalettes={
"Celenes by Sweden":['#086f6d','#ffd767'],"Justin Beauty":['#b5234e','#f7ee63'],"The Purest Solutions":['#293db7','#d4f374'],"L'Occitane":['#a24b12','#ffe15b'],"Caudalie":['#4a235f','#d8ef78'],"Flormar":['#eb173f','#f2ed64'],"Yves Rocher":['#215b35','#ebef7a']
};
const posterHeadlines={
'celenes-sale':['%60 net','indirim'],
'justin-cart':['Sepette','200 TL indirim'],
'tps-tester':['Her siparişe','tester hediye'],
'loccitane-sale':['%30’a varan','indirim'],
'caudalie-shipping':['Ücretsiz','kargo'],
'yves-sale':['Cilt ve saç','bakımında','%40 net indirim'],
'flormar-code':['İlk alışverişe','%25 indirim'],
'justin-code':['İlk alışverişe','%15 indirim'],
'flormar-multi':['2 alana','2 hediye'],
'caudalie-gift':['Deneme boy','hediye'],
'loccitane-gift':['Verbena balm','hediye'],
'justin-club':['Her 1 TL’ye','1 puan']
};
const artworkSizes={};
function imagePoster(o,size="large"){const format=size==="square"?"square":size==="detail"?"detail":size==="large"?"large":"compact";return campaignArt[o.id][format];}
function poster(o,size){const format=size==='square'?'square':size==='detail'?'detail':size==='large'?'large':'compact';const m=artworkSizes[o.id]?.[format]||{width:format==='detail'?1200:format==='square'?768:720,height:format==='detail'?800:format==='square'?768:1080,background:'#fff'};return `<button class="ps-poster ${size} cursor-interaction" data-offer="${esc(o.id)}" style="--artwork-frame:${m.background}" aria-label="${esc(o.brand+': '+o.title)}"><img class="ps-posterimage" width="${m.width}" height="${m.height}" loading="lazy" decoding="async" src="${imagePoster(o,size)}" alt="${esc(o.brand+' · '+o.title+' · '+o.sub)}"></button>`}
function carousel(arr,size){return `<div class="ps-carousel ${size}" aria-label="${size==='large'?'Öne çıkan kampanyalar':'Diğer kampanyalar'}">${arr.map(o=>poster(o,size)).join('')}</div>`}
let categoryScroll=0;
let selectedCategory='Kampanya Kodu';
const categoryIconBoxes=[[12,28,86,61],[110,19,87,75],[213,14,65,86],[305,18,85,77],[14,116,83,72],[111,112,78,77],[212,112,76,77],[309,112,79,78],[7,211,93,69],[100,211,93,66],[205,207,84,75],[305,203,86,78]];
const polishedIconBoxes={'Kampanya Kodu':[28,235,405,335],'Son Gün':[449,195,376,390],'Sepette İndirim':[820,200,420,390],'Hediyeli Alışveriş':[32,635,393,410],'Üyelere Özel':[442,679,380,360],'Kargo Avantajı':[827,681,412,365]};
function categoryIconStyle(name,size=46){if(name==='Sepette İndirim')return `background-image:url('assets/category-polished-cart.webp');background-size:contain;background-position:center;`;if(name==='Son Gün')return `background-image:url('assets/category-polished-last-day.webp');background-size:contain;background-position:center;`;if(polishedIconBoxes[name]){const [x,y,w,h]=polishedIconBoxes[name];const scale=(size-2)/Math.max(w,h);return `background-image:url('assets/category-polished.webp');background-size:${1254*scale}px ${1254*scale}px;background-position:${(size-w*scale)/2-x*scale}px ${(size-h*scale)/2-y*scale}px`;}
if(name==='Üyelere Özel')return `background-image:url('assets/category-members-clean.webp');background-size:contain;background-position:center;`;const [x,y,w,h]=categoryIconBoxes[categoryAtlasNames.indexOf(name)];const scale=(size-2)/Math.max(w,h);return `background-image:url('${categoryAtlas}');background-size:${400*scale}px ${300*scale}px;background-position:${(size-w*scale)/2-x*scale}px ${(size-h*scale)/2-y*scale}px`;}
function clockAngles(now=new Date()){const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Istanbul',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(now).map(p=>[p.type,p.value]));const seconds=Number(p.second)+now.getMilliseconds()/1000;const minutes=Number(p.minute)+seconds/60;return {hour:(Number(p.hour)%12+minutes/60)*30,minute:minutes*6};}
function liveClock(){const a=clockAngles();return `<span class="ps-liveclock" aria-hidden="true"><span class="ps-clockhand ps-clockhour" style="--clock-angle:${a.hour}deg"></span><span class="ps-clockhand ps-clockminute" style="--clock-angle:${a.minute}deg"></span><span class="ps-clockpin"></span></span>`;}
function categoryArtwork(n){return `<span class="ps-iconart"><span class="ps-atlasicon" aria-hidden="true" style="${categoryIconStyle(n)}"></span></span>`;}
function categoryRounds(){return `<div class="ps-rounds" aria-label="Kampanya türleri">${cats.slice(1).map(([n])=>{const i=categoryAtlasNames.indexOf(n);return `<button data-type="${n}" aria-pressed="${type===n}" class="cursor-interaction ${type===n?'active':''}"><b>${categoryArtwork(n)}</b><span>${n}</span></button>`;}).join('')}</div>`}
function home(){return `${header()}<main class="ps-main ps-home">${categoryRounds()}<div id="ps-discovery">${discovery()}</div></main>`}
const codeBannerArt={};
let codeBannerIndex=0;
function codeFeature(arr){
const coded=arr.filter(o=>o.hasCode);
if(!coded.length)return '';
return `<section class="ps-codefeature" aria-label="Kampanya kodlu fırsatlar"><h2 class="ps-codeheading">Kampanya Kodu</h2><div class="ps-coderail" aria-roledescription="kampanya slaytları">${coded.map(o=>`<button type="button" data-offer="${esc(o.id)}" class="ps-codebanner cursor-interaction ${o.brand==='Justin Beauty'?'justin':''}" aria-label="${esc(o.brand+': '+o.title)}"><img class="ps-codebanner-art" src="${codeBannerArt[o.id]||offerTicket(o)}" alt="${esc(o.brand+': '+o.title+' · '+o.sub)}"></button>`).join('')}</div>${coded.length>1?`<div class="ps-codedots" aria-label="Kampanya seç">${coded.map((o,i)=>`<button type="button" data-code-slide="${i}" class="cursor-interaction" aria-current="${i===0}" aria-label="${esc(o.brand)} kampanyasını göster"></button>`).join('')}</div>`:''}</section>`;
}
function moveCodeBanner(i,behavior='smooth'){
const rail=root.querySelector('.ps-coderail');if(!rail||!rail.children.length)return;
codeBannerIndex=(i+rail.children.length)%rail.children.length;
rail.scrollTo({left:codeBannerIndex*rail.clientWidth,behavior});
root.querySelectorAll('.ps-codefeature:not(.ps-lastdayfeature) .ps-codedots button').forEach((b,n)=>b.setAttribute('aria-current',String(n===codeBannerIndex)));
}
root.addEventListener('scroll',e=>{
if(!e.target.classList?.contains('ps-coderail'))return;
const rail=e.target;codeBannerIndex=Math.round(rail.scrollLeft/Math.max(1,rail.clientWidth));
root.querySelectorAll('.ps-codefeature:not(.ps-lastdayfeature) .ps-codedots button').forEach((b,n)=>b.setAttribute('aria-current',String(n===codeBannerIndex)));
},true);
const codeBannerTimer=setInterval(()=>{
if(!root.isConnected){clearInterval(codeBannerTimer);return;}
if(view!=='home'||document.hidden)return;
const rail=root.querySelector('.ps-coderail');if(!rail||rail.children.length<2)return;
const box=rail.getBoundingClientRect(),viewport=screen.getBoundingClientRect();
if(box.bottom<=viewport.top||box.top>=viewport.bottom||rail.matches(':hover')||rail.contains(document.activeElement))return;
moveCodeBanner(codeBannerIndex+1,window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth');
},5000);
const lastDayArt={};

let lastDayIndex=0;
function lastDayTicket(o){const xml=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="400" viewBox="0 0 1200 400"><rect width="1200" height="400" rx="36" fill="#171719"/><path d="M890 0v400" stroke="#f6f0df" stroke-width="4" stroke-dasharray="12 12"/><circle cx="890" cy="0" r="26" fill="#fafafa"/><circle cx="890" cy="400" r="26" fill="#fafafa"/><rect x="44" y="34" width="152" height="44" rx="12" fill="#ff454b"/><text x="120" y="64" text-anchor="middle" font-family="Arial,sans-serif" font-size="25" font-weight="700" fill="#171719">SON GÜN</text><text x="44" y="130" font-family="Arial,sans-serif" font-size="36" fill="#f6f0df">${xml(o.brand)}</text><text x="44" y="217" font-family="Arial,sans-serif" font-size="52" font-weight="700" fill="#f6f0df">${xml(o.title)}</text><text x="44" y="286" font-family="Arial,sans-serif" font-size="30" fill="#f6f0df">${xml(o.sub)}</text><text x="44" y="351" font-family="Arial,sans-serif" font-size="25" fill="#ff7276">Bitmesine 24 saatten az kaldı</text><text x="1043" y="208" text-anchor="middle" font-family="Arial,sans-serif" font-size="72" font-weight="700" fill="#ff454b">24</text><text x="1043" y="250" text-anchor="middle" font-family="Arial,sans-serif" font-size="26" fill="#f6f0df">SAATTEN AZ</text></svg>`);}
function lastDayFeature(arr){const last=arr.filter(o=>isLastDay(o));if(!last.length)return '';
return `<section class="ps-codefeature ps-lastdayfeature" aria-label="Son gün kampanyaları"><h2 class="ps-codeheading">Son Gün</h2><div class="ps-lastdayrail" aria-roledescription="kampanya slaytları">${last.map(o=>`<button type="button" data-offer="${esc(o.id)}" class="ps-codebanner cursor-interaction" aria-label="${esc(o.brand+': '+o.title)}"><img class="ps-codebanner-art" src="${lastDayArt[o.id]||lastDayTicket(o)}" alt="${esc(o.brand+' · '+o.title+' · '+o.sub)}"></button>`).join('')}</div>${last.length>1?`<div class="ps-codedots ps-lastdaydots" aria-label="Son gün kampanyası seç">${last.map((o,i)=>`<button type="button" data-lastday-slide="${i}" class="cursor-interaction" aria-current="${i===0}" aria-label="${esc(o.brand)} kampanyasını göster"></button>`).join('')}</div>`:''}</section>`;}
function moveLastDay(i,behavior='smooth'){const rail=root.querySelector('.ps-lastdayrail');if(!rail||!rail.children.length)return;lastDayIndex=(i+rail.children.length)%rail.children.length;rail.scrollTo({left:lastDayIndex*rail.clientWidth,behavior});root.querySelectorAll('.ps-lastdaydots button').forEach((b,n)=>b.setAttribute('aria-current',String(n===lastDayIndex)));}
root.addEventListener('click',e=>{const b=e.target.closest('[data-lastday-slide]');if(b)moveLastDay(Number(b.dataset.lastdaySlide));});
root.addEventListener('scroll',e=>{if(!e.target.classList?.contains('ps-lastdayrail'))return;const rail=e.target;lastDayIndex=Math.round(rail.scrollLeft/Math.max(1,rail.clientWidth));root.querySelectorAll('.ps-lastdaydots button').forEach((b,n)=>b.setAttribute('aria-current',String(n===lastDayIndex)));},true);
function advanceLastDay(){if(!root.isConnected){clearInterval(lastDayTimer);return;}if(view!=='home'||document.hidden)return;const rail=root.querySelector('.ps-lastdayrail');if(!rail||rail.children.length<2)return;const box=rail.getBoundingClientRect(),viewport=screen.getBoundingClientRect();if(box.bottom<=viewport.top||box.top>=viewport.bottom||rail.matches(':hover')||rail.contains(document.activeElement))return;moveLastDay(lastDayIndex+1,window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth');}
const lastDayTimer=setInterval(advanceLastDay,5000);

function discovery(){const arr=offers.filter(o=>(usage==='Tümü'||usage===(o.mode||(o.id==='justin-club'?'Üyelik':'Kodsuz')))&&(o.brand+' '+o.title+' '+o.sub).toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));const top=arr.slice(0,20);const small=arr.slice(20).length?arr.slice(20):arr;return `${arr.length?'':`<div class="ps-empty" role="status">${query?'Aramana uygun kampanya bulunamadı.':'Yeni ayrıcalıklar yakında'}</div>`}${carousel(top,'large')}${codeFeature(arr)}${carousel(small,'small')}${lastDayFeature(arr)}${brandRounds()}${discountTiles()}`}
const discountRates={};
let discountThreshold='all';
const discountTileImages={"10":"assets/discountTileImages-10-art.webp","25":"assets/discountTileImages-25-art.webp","50":"assets/discountTileImages-50-art.webp","all":"assets/discountTileImages-all-art.webp"};
function discountTiles(){return '<h2 class="ps-discountheading">İndirim oranını seç, fırsatları kaçırma!</h2><div class="ps-discountgrid" aria-label="İndirim oranına göre keşfet">'+['10','25','50','all'].map(n=>'<button type="button" class="ps-discounttile cursor-interaction" data-discount="'+n+'" aria-label="'+(n==='all'?'Tüm indirimler':'%'+n+' ve üzeri')+'"><img src="'+discountTileImages[n]+'" alt="'+(n==='all'?'Tüm indirimler':'%'+n+' ve üzeri')+'"></button>').join('')+'</div>'}
function discountOffers(){return offers.filter(o=>discountThreshold==='all'?categoriesFor(o).some(c=>['Kampanya Kodu','Sepette İndirim','Ürün İndirimleri','İkinci Ürüne İndirim'].includes(c)):(discountRates[o.id]||0)>=Number(discountThreshold))}
function discountpage(){const arr=discountOffers();return `${back('İndirimler')}<main class="ps-main"><div class="ps-brandhead"><h2>${discountThreshold==='all'?'Tüm indirimler':'%'+discountThreshold+' ve üzeri'}</h2><p>${new Set(arr.map(o=>o.brand)).size} marka · ${arr.length} kampanya</p></div>${feed(arr)}</main>`}
function back(title){return `<div class="ps-back"><button data-action="back" class="ps-icon cursor-interaction" aria-label="Geri">${icon('chevron-left')}</button><span>${title}</span>${view==='detail'?`<button data-like="${esc(current.id)}" class="ps-icon cursor-interaction" aria-label="${favorites.has(current.id)?'Favorilerden çıkar':'Favorilere ekle'}" style="color:${favorites.has(current.id)?'#ff3131':'#74787f'}">${icon('bookmark')}</button>`:'<span style="width:36px"></span>'}</div>`}
let sheetSnap='middle',copyNotice=false,sheetDrag=null,sheetMoved=false;
function detailAction(o){if(!o.hasCode)return `<a class="ps-cta cursor-interaction" href="${esc(o.source)}" target="_blank" rel="noopener" style="margin-top:0">Kampanyaya git</a>`;if(revealed)return `<div class="ps-realcodereveal"><strong>${esc(o.code)}</strong><button data-copy-preview="1" class="cursor-interaction">${icon('copy')}Kopyala</button></div><p class="ps-slidehelp">${o.demo?'Örnek kod · Alışverişte geçerli değildir':'Kodu kampanya koşullarına göre kullan'}</p>`;return `<div class="ps-slide ps-realtrack"><span class="ps-trackglyph">${icon('chevron-right')}</span><span class="ps-tracklabel">Kodu görmek için sağa kaydır</span><input id="ps-reveal" type="range" min="0" max="100" value="0" aria-label="Kodu açmak için sağa kaydır veya sağ ok tuşunu kullan"></div><p class="ps-slidehelp">Kodu açmak için butonu sağa kaydır</p>`}
function demoBenefits(){return '';}
function detail(){const o=current;const channel=o.demo?'Taslak kampanya':o.source.replace(/^https?:\/\//,'').split('/')[0].replace(/^www\./,'');return `<main class="ps-realdetail"><header class="ps-detailtop"><button data-action="back" class="cursor-interaction" aria-label="Geri">${icon('chevron-left')}</button><strong>Prime Ayrıcalıkları</strong><button data-like="${esc(o.id)}" role="switch" aria-checked="${favorites.has(o.id)}" class="cursor-interaction ${favorites.has(o.id)?'active':''}" aria-label="${esc(o.brand)} ${favorites.has(o.id)?'favorilerden çıkar':'favorilere ekle'}" aria-pressed="${favorites.has(o.id)}">${icon('bookmark')}</button></header><div class="ps-nativehero"><img width="1200" height="800" decoding="async" fetchpriority="high" src="${imagePoster(o,'detail')}" alt="${esc(o.brand+' kampanya görseli')}"></div><section class="ps-detailsheet" data-snap="${sheetSnap}" aria-label="Kampanya detay paneli"><div class="ps-dragzone"><button class="ps-sheethandle cursor-interaction" data-sheet-toggle="1" aria-label="Detay panelini genişlet veya daralt" aria-expanded="${sheetSnap==='expanded'}"><span></span></button><div class="ps-sheetpills"><span>${esc(o.brand)}</span><span>${esc(channel)}</span></div><h1>${esc(o.title)}</h1></div><div class="ps-sheetbody"><p>${esc(o.terms)}</p>${demoBenefits(o)}<div class="ps-sheetdate">${icon('calendar-days')}<span>Kampanya bitiş tarihi<strong>${esc(o.expiry)}</strong></span></div></div></section><div class="ps-slidefooter">${detailAction(o)}</div>${copyNotice?`<div class="ps-copyoverlay"><section class="ps-copydialog" role="dialog" aria-modal="true" aria-label="Kod kopyalandı"><button data-close-copy="1" class="ps-copyhandle cursor-interaction" aria-label="Kod penceresini kapat"><span></span></button><h2>Kod kopyalandı</h2><p>${o.demo?'Bu örnek kod gerçek alışverişte geçerli değildir.':'Kampanya kodunu alışveriş sırasında kullanabilirsin.'}</p><div class="ps-code">${esc(o.code)}</div>${o.demo?'':`<a href="${esc(o.source)}" target="_blank" rel="noopener" class="ps-cta cursor-interaction">Web sitesine git${icon('external-link')}</a>`}</section></div>`:''}</main>`}
function brands(){const names=[...new Set(offers.map(o=>o.brand))],filtered=names.filter(n=>n.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));return `${header()}<main class="ps-main"><div class="ps-brandgrid">${names.map(n=>`<button class="ps-brandtile cursor-interaction" data-brand="${esc(n)}" aria-label="${esc(n)} kampanyalarını aç" ${filtered.includes(n)?'':'hidden'}><img class="ps-tilelogo" loading="lazy" decoding="async" src="${logos[n]}" alt="${esc(n)} logosu"></button>`).join('')}</div><div class="ps-empty" id="ps-brand-empty" role="status" ${filtered.length?'hidden':''}>Aramana uygun marka bulunamadı.</div></main>`}
function brandpage(){const arr=offers.filter(o=>o.brand===brand);return `${back('Markanın kampanyaları')}<main class="ps-main"><div class="ps-brandhead"><h2>${esc(brand)}</h2><p>${arr.length} kampanya</p></div><div class="ps-head"><h2>Tüm kampanyalar</h2></div>${feed(arr)}</main>`}
function categorypage(){const arr=offers.filter(o=>categoriesFor(o).includes(selectedCategory));const names=[...new Set(arr.map(o=>o.brand))];return `${back('Kategorinin kampanyaları')}<main class="ps-main ps-categorypage"><div class="ps-categoryhead"><span class="ps-categoryart" aria-hidden="true">${categoryArtwork(selectedCategory)}</span><div><h2>${esc(selectedCategory)}</h2><p>${names.length} marka · ${arr.length} kampanya</p></div></div><div class="ps-nativegrid" aria-label="${esc(selectedCategory)} kategorisindeki markalar">${arr.length?nativeGroups(names,arr):'<div class="ps-empty">Bu kategoride henüz kampanya bulunmuyor.</div>'}</div></main>`}
function filter(){return `${back('Filtrele')}<main class="ps-main"><h2>Kampanya türü</h2><select id="ps-type" class="ps-select" aria-label="Kampanya türü">${cats.map(([c])=>`<option ${type===c?'selected':''}>${c}</option>`).join('')}</select><h2>Kullanım yöntemi</h2>${usageFilter()}<button data-action="apply" class="ps-cta cursor-interaction">Kampanyaları göster</button><button data-action="reset" class="ps-filter ps-reset cursor-interaction">Filtreleri temizle</button></main>`}
let campaignBrand='Tümü',campaignGroup='',campaignOrigin='campaigns';
function nativeHeader(title){return `<header class="ps-nativebar"><button type="button" data-action="back" class="cursor-interaction" aria-label="Geri">${icon('chevron-left')}</button><strong>${title}</strong><button type="button" data-native-search="1" class="cursor-interaction" aria-label="Ara">${icon('search')}</button></header>`}
function nativeFavorites(){const arr=offers.filter(o=>favorites.has(o.id));return `<main class="ps-nativepage">${nativeHeader('Favoriler')}${arr.length?`<div class="ps-nativegrid">${arr.map(o=>`<article class="ps-nativefavorite"><button class="ps-nativelogo cursor-interaction" data-offer="${esc(o.id)}" aria-label="${esc(o.brand)} kampanyasını aç"><img src="${logos[o.brand]}" alt="${esc(o.brand)} logosu"></button><button class="ps-nativesave cursor-interaction" data-like="${esc(o.id)}" aria-label="${esc(o.brand)} favorilerden çıkar" aria-pressed="true">${icon('bookmark')}</button></article>`).join('')}</div>`:`<div class="ps-nativeempty">${icon('bookmark')}<h2>Henüz favorin yok</h2><p>Fırsatların yanındaki yer imiyle<br>beğendiklerini kaydedebilirsin.</p><button data-view="brands" class="cursor-interaction">Fırsatları keşfet</button></div>`}</main>`}
function nativeCampaigns(){const names=brandNames.filter(n=>(campaignBrand==='Tümü'||campaignBrand===n)&&n.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));return `<main class="ps-nativepage">${nativeHeader('Kampanyalar')}<label class="ps-search">${icon('search')}<input id="ps-native-query" type="search" placeholder="Marka ara" aria-label="Marka ara" value="${esc(query)}"></label><div class="ps-nativefilters">${['Tümü',...brandNames].map(n=>`<button type="button" class="cursor-interaction ${n===campaignBrand?'active':''}" data-campaign-brand="${esc(n)}" aria-pressed="${n===campaignBrand}">${esc(n)}</button>`).join('')}</div><div class="ps-nativegrid" id="ps-native-results">${nativeGroups(names)}</div></main>`}
function nativeGroups(names,sourceOffers=offers){return names.map(n=>{const arr=sourceOffers.filter(o=>o.brand===n);if(!arr.length)return '';return `<article class="ps-nativegroup" data-brand-group="${esc(n)}"><div class="ps-nativerail" tabindex="0" role="group" aria-roledescription="kampanya slaytları" aria-label="${esc(n)} kampanyalarını aç">${arr.map(o=>`<button type="button" class="cursor-interaction" data-campaign-group="${esc(n)}" data-offer-id="${esc(o.id)}" aria-label="${esc(n)} kampanyalarını aç"><img width="768" height="768" loading="lazy" decoding="async" src="${imagePoster(o,'square')}" alt="${esc(o.title)}"></button>`).join('')}</div>${arr.length>1?`<span class="ps-nativecount" aria-label="${arr.length} kampanya">${arr.length}</span><div class="ps-nativedots" aria-hidden="true">${arr.map((o,i)=>`<span class="${i===0?'current':''}"></span>`).join('')}</div>`:''}</article>`}).join('')||'<div class="ps-empty">Marka bulunamadı</div>'}
function nativeCampaignGroup(){const arr=offers.filter(o=>o.brand===campaignGroup&&(campaignOrigin!=='category'||categoriesFor(o).includes(selectedCategory)));return `<main class="ps-nativepage">${nativeHeader('Marka kampanyaları')}<h2>${esc(campaignGroup)}</h2><p class="ps-sub">${campaignOrigin==='category'?esc(selectedCategory)+' · ':''}${arr.length} kampanya</p><div class="ps-nativelist">${arr.map(o=>`<button type="button" class="cursor-interaction" data-offer="${esc(o.id)}" aria-label="${esc(o.title)} detayları"><img src="${imagePoster(o,'square')}" alt="${esc(o.brand)}"><span><strong>${esc(o.title)}</strong><small>Kampanyayı incele</small></span>${icon('chevron-right')}</button>`).join('')}</div></main>`}

const testflightReference={"version":"1.0.1","build":"142.1","commit":"26bcf941968e1a3a49993add45748cca94c9404a","uploadRun":41185972943,"statusRun":41186442406,"appBlob":"3ef3044b8dd3b5970d20cf12518c63fbd84e0f32","cssBlob":"f54ba90bff5d0b681f60bfbc35fd15f2e921af48","notificationsAvailable":false};
let settingsNotifications=false,settingsPhoto=readLocal('lmprime-photo',null);
const settingsViews=['settings','personal','notifications','privacy','terms','deleteAccount'];
const settingIcon=n=>icon(n).replace('data-lucide','class="icon" data-lucide');
const settingsAvatar=()=>settingsPhoto?`<img class="profile-photo" src="${settingsPhoto}" alt="Profil fotoğrafın">`:settingIcon('user-round');
function settingsHeader(title){return `<header class="topbar"><button class="circle cursor-interaction" data-settings-back="1" aria-label="Geri">${settingIcon('chevron-left')}</button><span class="page-title">${title}</span><button class="circle cursor-interaction" data-view="campaigns" aria-label="Ara">${settingIcon('search')}</button></header>`}
function settingsMenu(name,i,target){return `<button class="cursor-interaction" data-view="${target}">${settingIcon(i)}${name}<span class="last">${settingIcon('chevron-right')}</span></button>`}
function settingsPage(){return `<main class="ps-settingsnative">${settingsHeader('Ayarlar')}<button class="profile-card cursor-interaction" data-view="personal"><span class="profile-icon">${settingsAvatar()}<span class="edit-dot">✎</span></span><strong>Misafir</strong>${settingIcon('chevron-right')}</button><div class="menu grouped">${settingsMenu('Gizlilik','shield-check','privacy')}${settingsMenu('Verilerimi sil','file-text','deleteAccount')}${settingsMenu('Kullanıcı Sözleşmesi','file-text','terms')}</div></main>`}
function settingsSubpage(){let title='',body='';
 if(view==='personal'){title='Misafir tercihleri';body=`<h1>Tercihlerin</h1><p class="sub">Deneyimini kendine göre düzenle.</p><section class="photo-settings"><div class="profile-icon">${settingsAvatar()}</div><label class="photo-pick cursor-interaction" for="ps-settings-photo">Fotoğraf ${settingsPhoto?'değiştir':'seç'}</label><input id="ps-settings-photo" type="file" accept="image/*" class="sr-only">${settingsPhoto?'<button class="text-link cursor-interaction" data-remove-settings-photo="1">Fotoğrafı kaldır</button>':''}<p class="sub">Fotoğraf yalnızca bu cihazda saklanır.</p></section>`;}
 if(view==='notifications'){title='Bildirimlerim';body=`<div class="ps-head"><h2>Bildirimlerin</h2></div><div class="ps-nativeempty"><h2>Henüz bildirimin yok</h2><p>Yeni ayrıcalıklar burada görünecek.</p></div>`;}
 if(view==='privacy'||view==='terms'){title=view==='privacy'?'Gizlilik':'Kullanıcı Sözleşmesi';body=`<div class="document">${view==='privacy'?settingsPrivacy:settingsTerms}</div>`;}
 if(view==='deleteAccount'){title='Verileri sil';body=`<div class="document"><h1>Verilerimi sil</h1><p>Teknik oturumun ve varsa bildirim kayıtların silinir. Bu cihazdaki favorilerin, profil fotoğrafın ve kaydedilen kampanya kodların da kaldırılır.</p><p>Bu işlem geri alınamaz. Sonrasında uygulama bilgi istemeden yeniden açılır. Kimliğe bağlanmayan kampanya istatistikleri ve normal saklama süresine tabi güvenlik kayıtları korunur.</p><button class="primary cursor-interaction" data-settings-delete="1">Verileri sil</button><button class="text-link cursor-interaction" data-view="settings">Vazgeç</button></div>`;}
 return `<main class="ps-settingsnative">${settingsHeader(title)}${body}</main>`;
}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 
 if(d.settingsNotifications){settingsNotifications=!settingsNotifications;render();}
 if(d.removeSettingsPhoto){settingsPhoto=null;writeLocal('lmprime-photo',null);render();}
 if(d.settingsDelete){deleteData();}
});
root.addEventListener('change',e=>{if(e.target.id!=='ps-settings-photo')return;const file=e.target.files?.[0];if(!file||!file.type.startsWith('image/'))return;if(file.size>5*1024*1024){showError('Lütfen 5 MB’den küçük bir fotoğraf seç.');return;}const reader=new FileReader();reader.onload=()=>{settingsPhoto=reader.result;writeLocal('lmprime-photo',settingsPhoto);render();};reader.readAsDataURL(file);});

const settingsTerms="<h1>Literatür Masası Prime Kullanıcı Sözleşmesi</h1><p>Son güncelleme: 21.10.2026</p><p>Hizmeti sunan: Doğukan Paçacı · İletişim: marka@literaturmasasi.com</p><h2>Kapsam ve kullanım</h2><p>Uygulama açılış logosundan sonra doğrudan açılır. Hesap, şifre, erişim kodu, telefon veya e-posta gerekmez. Kampanyaları inceleyebilir, favorilerine ekleyebilir ve kampanya kodlarını görüntüleyebilirsin.</p><h2>Kampanyalar</h2><p>Her teklif ilgili markanın koşulları, stokları ve geçerlilik süresiyle sınırlıdır. Örnek olarak işaretlenen kampanyalar alışveriş hakkı sağlamaz. Uygulama içinde satış, ödeme veya sipariş yapılmaz. Alışveriş ve teslimat ilgili satıcının sorumluluğundadır.</p><h2>İçerik ve sorumluluk</h2><p>İçerikler tıbbi tavsiye değildir. Ürün kullanımı hakkında sağlık uzmanına danış. Hizmeti hukuka uygun kullan; otomatik kötüye kullanım ve yetkisiz yönetim işlemleri yasaktır.</p><h2>İletişim</h2><p>Destek ve talepler için marka@literaturmasasi.com adresine yazabilirsin.</p>";
const settingsPrivacy="<h1>Literatür Masası Prime Gizlilik Bilgilendirmesi</h1><p>Son güncelleme: 21.10.2026</p><p>Veri sorumlusu: Doğukan Paçacı · marka@literaturmasasi.com</p><h2>Uygulamanın açılması</h2><p>Hesap, şifre, telefon veya e-posta istenmez. Hizmetin çalışması için cihazda rastgele kurulum kimliği ve teknik oturum anahtarı oluşturulur. Anahtar iOS Keychain içinde tutulur; sunucuda yalnızca özeti saklanır. Bu teknik kayıtlar kişisel iletişim bilgisi içermez. Oturum en fazla 30 gün geçerlidir ve gerektiğinde otomatik yenilenir.</p><h2>Cihazdaki bilgiler</h2><p>Favoriler ve isteğe bağlı profil fotoğrafı cihazda saklanır. Fotoğraf seçimi isteğe bağlıdır; fotoğraf sunucuya gönderilmez.</p><h2>Hizmet ve güvenlik</h2><p>Kampanya kodu görüntülemeleri kampanya istatistikleri için kaydedilir. Bildirimler etkinse tercihler ve okunma bilgileri teknik oturumla ilişkilendirilebilir. Ağ adresi kötüye kullanım sınırlaması için işlenir; veritabanındaki güvenlik sayaçları zaman aralığına bağlı özet anahtarlardır. Yönetim paneline erişim ayrıca korunur.</p><h2>Saklama ve silme</h2><p>Ayarlar → Verilerimi sil seçeneğiyle cihazdaki favori, fotoğraf ve tercihler ile geçerli teknik oturumun sunucudaki kayıtları silinebilir. Sonrasında uygulama kişisel bilgi istemeden kullanılabilir. Süresi dolan oturumlar sonraki açılışlarda temizlenir. Kimliğe bağlanmayan kampanya istatistikleri ve normal saklama süresine tabi güvenlik kayıtları bu işlemden etkilenmez. Destek yazışmaları talebin çözümü ve yasal yükümlülükler için gerekli süreyle saklanır.</p><h2>Haklarınız</h2><p>Bilgi, düzeltme ve silme taleplerinizi marka@literaturmasasi.com adresine iletebilirsiniz.</p>";

function syncDetailPanel(){const sheet=root.querySelector('.ps-detailsheet'),image=root.querySelector('.ps-nativehero');if(!sheet||!image)return;const h=screen.clientHeight;const middle=image.offsetTop+image.offsetHeight+12;sheet.style.setProperty('--sheet-middle-top',middle+'px');sheet.style.setProperty('--sheet-collapsed-top',Math.max(h*.52,middle+h*.08)+'px');}
function render(){if(!loaded){screen.innerHTML=loadError?'<div class="ps-nativeempty" role="alert"><h2>Kampanyalar yüklenemedi</h2><p>Bağlantını kontrol ederek tekrar dene.</p><button data-retry="1">Tekrar dene</button></div>':'<div class="launch-splash" role="status"><img src="assets/literatur-masasi-original.png" alt="Literatür Masası Prime"><p>Yükleniyor…</p></div>';return;}const nav=root.querySelector('.ps-nav');if(nav)nav.style.display=(view==='detail'||settingsViews.includes(view))?'none':'';screen.innerHTML=view==='home'?home():view==='brands'?brands():view==='brand'?brandpage():view==='category'?categorypage():view==='discount'?discountpage():view==='detail'?detail():view==='filter'?filter():view==='campaigns'?nativeCampaigns():view==='campaignGroup'?nativeCampaignGroup():view==='favorites'?nativeFavorites():view==='settings'?settingsPage():settingsViews.includes(view)?settingsSubpage():home();root.querySelectorAll('.ps-previewnav [data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));root.querySelectorAll('.ps-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===(view==='campaignGroup'?'campaigns':view==='detail'?(returnView==='campaignGroup'?'campaigns':returnView):view)));root.querySelectorAll('.ps-nativerail').forEach(rail=>rail.addEventListener('scroll',()=>{const i=Math.round(rail.scrollLeft/Math.max(1,rail.clientWidth));rail.parentElement.querySelectorAll('.ps-nativedots span').forEach((dot,n)=>dot.classList.toggle('current',n===i));},{passive:true}));screen.querySelectorAll('img').forEach(img=>{img.decoding='async';if(!img.closest('.ps-nativehero')&&!img.closest('.ps-carousel.large'))img.loading='lazy';});syncDetailPanel();if(typeof lucide!=='undefined')lucide.createIcons();}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
if(d.retry){start();return;}if(d.lastdaySlide!==undefined||d.settingsDelete||d.removeSettingsPhoto)return;
if(d.codeSlide!==undefined){moveCodeBanner(Number(d.codeSlide));return;}
if(d.copyPreview){copyCurrentCode();return;}
if(d.settingsBack||d.action==='back'){const p=navigation.pop();if(p){restorePage(p);return;}view=view==='settings'?'home':settingsViews.includes(view)?'settings':'home';render();screen.scrollTop=0;return;}
const previous=capturePage();
const route=d.view||d.discount||d.campaignGroup||d.brand||d.offer||d.type||d.nativeSearch;
if(route){if(d.view&&['home','brands','campaigns','favorites'].includes(d.view))navigation.length=0;else navigation.push(previous);}
if(d.view){if(d.view==='home')categoryScroll=0;if(d.view==='filter')returnView=view;view=d.view;query='';type='Tümü';usage='Tümü';}
else if(d.discount){discountThreshold=d.discount;type='Tümü';usage='Tümü';query='';view='discount';}
else if(d.campaignBrand){campaignBrand=d.campaignBrand;view='campaigns';}
else if(d.campaignGroup){campaignOrigin=view==='category'?'category':'campaigns';campaignGroup=d.campaignGroup;view='campaignGroup';}
else if(d.nativeSearch){const input=root.querySelector('#ps-native-query');if(input){navigation.pop();input.focus();return;}view='campaigns';query='';}
else if(d.brand){brand=d.brand;type='Tümü';usage='Tümü';query='';view='brand';}
else if(d.offer){returnView=view;current=offers.find(o=>o.id===d.offer);if(!current)return;view='detail';revealed=false;sheetSnap='middle';copyNotice=false;}
else if(d.sheetToggle){if(sheetMoved){sheetMoved=false;return;}sheetSnap=sheetSnap==='middle'?'expanded':sheetSnap==='expanded'?'collapsed':'middle';}
else if(d.closeCopy){closeCopySheet();return;}
else if(d.reveal){revealCode();return;}
else if(d.usage){usage=d.usage;}
else if(d.type){categoryScroll=root.querySelector('.ps-rounds')?.scrollLeft||0;selectedCategory=d.type;type='Tümü';usage='Tümü';query='';view='category';}
else if(d.like){favorites.has(d.like)?favorites.delete(d.like):favorites.add(d.like);persistFavorites();}
else if(d.action==='apply'){view=returnView;}
else if(d.action==='reset'){type='Tümü';usage='Tümü';query='';view=returnView;}
render();if(route)screen.scrollTop=0;else screen.scrollTop=previous.y;
const categoryStrip=root.querySelector('.ps-rounds');if(categoryStrip)categoryStrip.scrollLeft=categoryScroll;
});
root.addEventListener('input',e=>{if(e.target.id==='ps-native-query'){query=e.target.value;root.querySelector('#ps-native-results').innerHTML=nativeGroups(brandNames.filter(n=>(campaignBrand==='Tümü'||campaignBrand===n)&&n.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr'))));return;}if(e.target.id==='ps-reveal'&&Number(e.target.value)>85){revealCode();return;}if(e.target.id==='ps-search'){query=e.target.value;const discoveryEl=root.querySelector('#ps-discovery');if(discoveryEl){discoveryEl.innerHTML=discovery();if(typeof lucide!=='undefined')lucide.createIcons();return;}const el=root.querySelector('#ps-feed');if(el){el.innerHTML=feed(offers);if(typeof lucide!=='undefined')lucide.createIcons();}else if(view==='brands'){const filtered=offers.map(o=>o.brand).filter((n,i,a)=>a.indexOf(n)===i).filter(n=>n.toLocaleLowerCase('tr').includes(query.toLocaleLowerCase('tr')));root.querySelectorAll('[data-brand]').forEach(b=>{if(b.closest('.ps-brandgrid'))b.hidden=!filtered.includes(b.dataset.brand);});const empty=root.querySelector('#ps-brand-empty');if(empty)empty.hidden=filtered.length>0;}}});
let copyDrag=null,copySuppressClickUntil=0;
function closeCopySheet(){copyDrag=null;copyNotice=false;render();screen.querySelector('[data-copy-preview]')?.focus();}
function copySheetDismissal(dy,elapsed,height){return dy>=Math.min(80,height*.25)||(dy>24&&dy/Math.max(elapsed,1)>.6);}
root.addEventListener('click',e=>{if(Date.now()<copySuppressClickUntil&&e.target.closest('.ps-copydialog')){e.preventDefault();e.stopImmediatePropagation();return;}if(copyNotice&&e.target.classList.contains('ps-copyoverlay'))closeCopySheet();},true);
root.addEventListener('pointerdown',e=>{if(!copyNotice||e.button!==0)return;const sheet=e.target.closest('.ps-copydialog');if(!sheet)return;if(e.target.closest('a,input,button')&&!e.target.closest('.ps-copyhandle'))return;copyDrag={id:e.pointerId,x:e.clientX,y:e.clientY,time:Date.now(),sheet,dy:0};e.target.setPointerCapture?.(e.pointerId);});
root.addEventListener('pointermove',e=>{if(!copyDrag||e.pointerId!==copyDrag.id)return;const dy=Math.max(0,e.clientY-copyDrag.y);if(Math.abs(e.clientX-copyDrag.x)>dy+12)return;copyDrag.dy=dy;if(dy>6){copyDrag.sheet.classList.add('ps-copydragging');copyDrag.sheet.style.transform=`translateY(${dy}px)`;const overlay=copyDrag.sheet.closest('.ps-copyoverlay');overlay.style.backgroundColor=`rgba(0,0,0,${Math.max(.1,.4-dy/900)})`;if(e.cancelable)e.preventDefault();}},{passive:false});
root.addEventListener('pointerup',e=>{if(!copyDrag||e.pointerId!==copyDrag.id)return;const d=copyDrag;copyDrag=null;if(d.dy>6)copySuppressClickUntil=Date.now()+350;if(copySheetDismissal(d.dy,Date.now()-d.time,d.sheet.offsetHeight)){closeCopySheet();return;}d.sheet.classList.remove('ps-copydragging');d.sheet.style.transform='';d.sheet.closest('.ps-copyoverlay').style.backgroundColor='';});
root.addEventListener('pointercancel',()=>{if(!copyDrag)return;copyDrag.sheet.classList.remove('ps-copydragging');copyDrag.sheet.style.transform='';copyDrag.sheet.closest('.ps-copyoverlay').style.backgroundColor='';copyDrag=null;});
root.addEventListener('pointerdown',e=>{if(!e.target.closest('.ps-dragzone'))return;const sheet=root.querySelector('.ps-detailsheet');sheetMoved=false;sheetDrag={y:e.clientY,top:sheet.offsetTop,sheet,moved:false};sheet.classList.add('ps-dragging');});
root.addEventListener('pointermove',e=>{if(!sheetDrag)return;const h=screen.clientHeight,dy=e.clientY-sheetDrag.y;if(Math.abs(dy)>5)sheetDrag.moved=true;sheetDrag.sheet.style.top=Math.max(h*.1,Math.min(h*.58,sheetDrag.top+dy))+'px';});
root.addEventListener('pointerup',()=>{if(!sheetDrag)return;const h=screen.clientHeight,ratio=sheetDrag.sheet.offsetTop/h;sheetDrag.sheet.classList.remove('ps-dragging');sheetMoved=sheetDrag.moved;if(sheetDrag.moved){sheetSnap=ratio<.25?'expanded':ratio>.46?'collapsed':'middle';sheetDrag.sheet.style.top='';sheetDrag.sheet.dataset.snap=sheetSnap;}sheetDrag=null;});
root.addEventListener('pointercancel',()=>{if(sheetDrag){sheetDrag.sheet.classList.remove('ps-dragging');sheetDrag.sheet.style.top='';sheetDrag=null;}});
let lastDayMembership=offers.filter(o=>isLastDay(o)).map(o=>o.id).join('|');
const lastDayRefresh=setInterval(()=>{if(!root.isConnected){clearInterval(lastDayRefresh);return;}if(document.hidden)return;const membership=offers.filter(o=>isLastDay(o)).map(o=>o.id).join('|');if(membership===lastDayMembership)return;lastDayMembership=membership;if(view==='home'||view==='category'){const y=screen.scrollTop;render();screen.scrollTop=y;}},1000);
root.addEventListener('keydown',e=>{const rail=e.target.closest('.ps-nativerail');if(!copyNotice&&rail&&e.target===rail&&['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();rail.scrollBy({left:(e.key==='ArrowRight'?1:-1)*rail.clientWidth,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}if(!copyNotice)return;if(e.key==='Escape'){copyNotice=false;render();screen.querySelector('[data-copy-preview]')?.focus();return;}if(e.key==='Tab'){const all=[...screen.querySelectorAll('.ps-copydialog button,.ps-copydialog a')];const first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
screen.addEventListener('error' ,e=>{if(e.target.tagName!=='IMG')return;const img=e.target;img.hidden=true;const fallback=document.createElement('span');fallback.className='ps-imageerror';fallback.setAttribute('role','img');fallback.setAttribute('aria-label',img.alt);fallback.textContent='Görsel yüklenemedi · '+img.alt;img.parentElement.append(fallback);},true);
root.addEventListener('change',e=>{if(e.target.id==='ps-type')type=e.target.value;});start();if(typeof ResizeObserver!=='undefined'){new ResizeObserver(syncDetailPanel).observe(screen);}
})();
